package cn.iocoder.yudao.module.zsjos.service.studentops; import cn.iocoder.yudao.framework.common.util.object.BeanUtils; import cn.iocoder.yudao.module.zsjos.controller.admin.studentops.vo.*; import cn.iocoder.yudao.module.zsjos.dal.dataobject.studentops.*; import cn.iocoder.yudao.module.zsjos.dal.mysql.account.MediaAccountMapper; import cn.iocoder.yudao.module.zsjos.dal.mysql.lead.PersonMapper; import cn.iocoder.yudao.module.zsjos.dal.mysql.studentops.*; import cn.iocoder.yudao.module.zsjos.framework.permission.ZsjosPermission; import jakarta.annotation.Resource; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*; import static cn.iocoder.yudao.framework.common.exception.util.ServiceExceptionUtil.exception; import static cn.iocoder.yudao.module.zsjos.enums.ZsjosErrorCodeConstants.*;
@Service public class StudentOpsService { @Resource private ExceptionTicketMapper exceptionMapper; @Resource private CooperationAssessmentMapper assessmentMapper; @Resource private MediaAccountMapper accountMapper; @Resource private PersonMapper personMapper; public List<ExceptionTicketRespVO> exceptions(Long uid){return exceptionMapper.selectByOwner(uid).stream().map(x->{var v=BeanUtils.toBean(x,ExceptionTicketRespVO.class);v.setAvailableActions("open".equals(x.getStatus())?List.of("resolve"):List.of());return v;}).toList();} @Transactional public Long createException(ExceptionTicketSaveReqVO req){if(accountMapper.selectById(req.getAccountId())==null)throw exception(CONTENT_ACCOUNT_INVALID);ExceptionTicketDO x=BeanUtils.toBean(req,ExceptionTicketDO.class);x.setExceptionNo("EX-"+UUID.randomUUID().toString().replace("-","").substring(0,16));x.setStatus("open");x.setVersion(0);exceptionMapper.insert(x);return x.getId();} @ZsjosPermission(bizType="media-exception",bizId="#id",action="resolve") @Transactional public void resolve(Long id,Integer version,String resolution){if(exceptionMapper.resolve(id,version,resolution)==0)throw exception(MEDIA_EXCEPTION_VERSION_CONFLICT);} @Transactional public Long assess(CooperationAssessmentSaveReqVO req,Long uid){if(accountMapper.selectById(req.getAccountId())==null||personMapper.selectById(req.getStudentPersonId())==null)throw exception(POSITIONING_REFERENCE_INVALID);CooperationAssessmentDO x=BeanUtils.toBean(req,CooperationAssessmentDO.class);x.setOperatorUserId(uid);x.setAssessedAt(LocalDateTime.now());assessmentMapper.insert(x);return x.getId();} public List<CooperationAssessmentDO> assessments(Long uid){return assessmentMapper.selectByOperator(uid);} }
